#!/usr/bin/env bash
#
# Runs scripts/size-check.sh on generated fixtures, one per case of the size-check table: the production
# and test caps and hard caps, the size: reason line and where it counts, generated files, CRLF and a
# missing final newline, a missing file, the -h and unknown-flag exits, an empty file and an absolute path.
# Fixtures are written under .temp/size-check-test/ on every run, so no large file is tracked.
# size-check-test.ps1 is the twin.
set -euo pipefail

readonly script_name="size-check-test.sh"

usage() {
  cat <<EOF
Usage: scripts/$script_name

Runs scripts/size-check.sh on generated fixtures and checks the exit code and messages of each case.

  -h, --help   Show this message.
EOF
}

fail() {
  echo "$script_name: $*" >&2
  exit 1
}

if [ "$#" -gt 0 ]; then
  case "$1" in
    -h | --help)
      usage
      exit 0
      ;;
    *)
      fail "unknown argument: $1"
      ;;
  esac
fi

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$repo_root"

work=".temp/size-check-test"
abs_work="$repo_root/$work"
rm -rf "$work"
mkdir -p "$work"

# write_block <block> <path>: appends the leading block of a fixture.
write_block() {
  case "$1" in
    none) ;;
    one)
      cat >>"$2" <<'EOF'
//! size: one long ported function
EOF
      ;;
    x)
      cat >>"$2" <<'EOF'
//! size: x
EOF
      ;;
    upper)
      cat >>"$2" <<'EOF'
//! Size: x
EOF
      ;;
    nodoc)
      cat >>"$2" <<'EOF'
// size: table of cases
use x;
EOF
      ;;
    late)
      cat >>"$2" <<'EOF'
use x;
//! size: late
EOF
      ;;
    item)
      cat >>"$2" <<'EOF'
//! Module.
/// size: x
fn a() {}
EOF
      ;;
    empty)
      cat >>"$2" <<'EOF'
//! size:
EOF
      ;;
    gen1)
      cat >>"$2" <<'EOF'
// @generated by gen_x.py
EOF
      ;;
    gen2)
      cat >>"$2" <<'EOF'
//! Module.
// @generated
EOF
      ;;
    docmix)
      cat >>"$2" <<'EOF'
//! The table helpers.
// size: x
EOF
      ;;
    attr)
      cat >>"$2" <<'EOF'
#![allow(
    clippy::unwrap_used,
)]
//! size: helper
EOF
      ;;
    *)
      fail "unknown block: $1"
      ;;
  esac
}

# fixture <rel path> <block> <total lines>: a file of that many lines, the leading block, then x lines.
fixture() {
  local path="$work/$1" have
  mkdir -p "$(dirname "$path")"
  : >"$path"
  write_block "$2" "$path"
  have="$(wc -l <"$path")"
  if [ $(($3 - have)) -gt 0 ]; then
    printf 'x\n%.0s' $(seq 1 $(($3 - have))) >>"$path"
  fi
}

fixture src/p800.rs none 800
fixture src/p801.rs none 801
fixture src/p801r.rs one 801
fixture src/p1200r.rs one 1200
fixture src/p1201r.rs one 1201
fixture src/nodoc.rs nodoc 801
fixture src/late.rs late 801
fixture src/itemdoc.rs item 801
fixture src/empty.rs empty 801
fixture src/gen1.rs gen1 5000
fixture src/gen2.rs gen2 5000
fixture src/docmix.rs docmix 801
fixture src/attr.rs attr 801
fixture tests/t1000.rs none 1000
fixture tests/t1001.rs none 1001
fixture src/m/tests/a.rs none 1001
fixture src/m/tests.rs none 1001
fixture tests/t1501r.rs x 1501
fixture src/upper.rs upper 801
fixture src/Tests/a.rs none 801
fixture src/zero.rs none 0

cat >"$work/src/crlf.rs" <<'EOF'
//! size: crlf
EOF
sed -i 's/$/\r/' "$work/src/crlf.rs"
printf 'x\r\n%.0s' $(seq 1 800) >>"$work/src/crlf.rs"

fixture src/noeol.rs none 800
printf 'x' >>"$work/src/noeol.rs"

failures=0
passes=0

# run_case <number> <expected exit> <expected stdout> <expected stderr lines, newline-separated, or empty>
# <files...>: runs the script on the files and checks the exit code, the exact stdout and each stderr line.
run_case() {
  local num="$1" want_exit="$2" want_out="$3" want_err="$4" rc=0 problems="" want_line
  shift 4
  scripts/size-check.sh "$@" >"$work/out-$num" 2>"$work/err-$num" || rc=$?
  [ "$rc" -eq "$want_exit" ] || problems+="exit $rc, want $want_exit; "
  [ "$(cat "$work/out-$num")" = "$want_out" ] || problems+="stdout '$(cat "$work/out-$num")', want '$want_out'; "
  if [ -n "$want_err" ]; then
    while IFS= read -r want_line; do
      grep -Fq -- "$want_line" "$work/err-$num" || problems+="stderr lacks '$want_line'; "
    done <<<"$want_err"
  fi
  if [ -z "$problems" ]; then
    passes=$((passes + 1))
  else
    echo "size-check-test.sh: case $num: $problems" >&2
    failures=$((failures + 1))
  fi
}

# run_case_head <number> <expected exit> <expected stdout line prefix> <files...>: like run_case, but checks only
# the start of the first stdout line (for -h, whose usage line names the script and differs per twin).
run_case_head() {
  local num="$1" want_exit="$2" want_head="$3" rc=0 problems="" first
  shift 3
  scripts/size-check.sh "$@" >"$work/out-$num" 2>"$work/err-$num" || rc=$?
  first="$(head -n 1 "$work/out-$num")"
  [ "$rc" -eq "$want_exit" ] || problems+="exit $rc, want $want_exit; "
  case "$first" in
    "$want_head"*) ;;
    *) problems+="first stdout line '$first', want prefix '$want_head'; " ;;
  esac
  if [ -z "$problems" ]; then
    passes=$((passes + 1))
  else
    echo "size-check-test.sh: case $num: $problems" >&2
    failures=$((failures + 1))
  fi
}

ok1="size-check: 1 files checked, 0 generated skipped"

run_case 1 0 "$ok1" "" "$work/src/p800.rs"
run_case 2 1 "" "$work/src/p801.rs: 801 lines, over the 800-line production cap without a size: line" "$work/src/p801.rs"
run_case 3 0 "$ok1" "" "$work/src/p801r.rs"
run_case 4 1 "" "$work/src/p1201r.rs: 1201 lines, over the 1200-line production hard cap" "$work/src/p1201r.rs"
run_case 5 0 "$ok1" "" "$work/src/nodoc.rs"
run_case 6 1 "" "$work/src/late.rs: 801 lines, over the 800-line production cap without a size: line" "$work/src/late.rs"
run_case 7 1 "" "$work/src/itemdoc.rs: 801 lines, over the 800-line production cap without a size: line" "$work/src/itemdoc.rs"
run_case 8 1 "" "$work/src/empty.rs: 801 lines, over the 800-line production cap without a size: line" "$work/src/empty.rs"
run_case 9 1 "" "$work/src/gen2.rs: 5000 lines, over the 1200-line production hard cap" "$work/src/gen2.rs" "$work/src/p800.rs"
run_case 10 0 "size-check: 1 files checked, 1 generated skipped" "" "$work/src/gen1.rs" "$work/src/p800.rs"
run_case 11 1 "" "$work/tests/t1001.rs: 1001 lines, over the 1000-line test cap without a size: line
$work/src/m/tests/a.rs: 1001 lines, over the 1000-line test cap without a size: line
$work/src/m/tests.rs: 1001 lines, over the 1000-line test cap without a size: line" "$work/tests/t1001.rs" "$work/src/m/tests/a.rs" "$work/src/m/tests.rs"
run_case 12 1 "" "size-check.sh: no hand-written .rs file checked" "$work/src/gen1.rs"
run_case 13 0 "$ok1" "" "$work/src/crlf.rs"
run_case 14 1 "" "$work/src/noeol.rs: 801 lines, over the 800-line production cap without a size: line" "$work/src/noeol.rs"
run_case 15 0 "$ok1" "" "$work/src/attr.rs"
run_case 16 1 "" "$work/src/nope.rs: no such file" "$work/src/nope.rs"
run_case 17 1 "" "$work/src/docmix.rs: 801 lines, over the 800-line production cap without a size: line" "$work/src/docmix.rs"
run_case 18 0 "$ok1" "" "$work/src/p1200r.rs"
run_case 19 0 "$ok1" "" "$work/tests/t1000.rs"
run_case 20 1 "" "$work/tests/t1501r.rs: 1501 lines, over the 1500-line test hard cap" "$work/tests/t1501r.rs"
run_case 21 1 "" "$work/src/upper.rs: 801 lines, over the 800-line production cap without a size: line" "$work/src/upper.rs"
run_case 22 1 "" "$work/src/Tests/a.rs: 801 lines, over the 800-line production cap without a size: line" "$work/src/Tests/a.rs"
run_case_head 23 0 "Usage:" -h
run_case 24 1 "" "unknown argument: --bogus" --bogus
run_case 25 0 "$ok1" "" "$work/src/zero.rs"
run_case 26 1 "" "$abs_work/src/p801.rs: 801 lines, over the 800-line production cap without a size: line" "$abs_work/src/p801.rs"

if [ "$failures" -gt 0 ]; then
  exit 1
fi
echo "size-check-test: $passes cases passed"
